Ext._define('web.intranet.link.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'web.intranet.link.Window',
    toolbarConfig: ['actions', '-', 'search', '->', '-', 'filter'],

    hideActions: ["remove", "copy", "edit"],

    hideItemsToolbar: ["edit", "remove"],

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: 'Titulo', dataIndex: 'name', id: 'autoExpandColumn'},
                    {header: 'Publicado em', dataIndex: 'published_date'},
                    {header: 'Ativo', dataIndex: 'active', width: 70, renderer: toolkit.util.formatIconYesNo, hidden: false},
                ]
            );

        return this._columnModel;
    },

    deleteItem: function(opts) {
        if(opts.signal == 'ok')
        {
            var loading = new Ext.LoadMask(xt.getBody(), {msg: 'Por favor aguarde...', store: opts.store});
            loading.show();
            xAjax.request({
                url: action('CMS/delete/json'),
                params: {id: opts.pars, model: opts.model, rel_id: opts.rel_id},
                success: function(response, options)
                {
                    loading.hide();
                    json = Ext.decode(response.responseText);
                    if(!json.success)
                        xAlert(json.msg);
                    else
                    {
                        if(opts.success)
                            opts.success();
                        if(opts.store)
                            opts.store.reload();
                    }
                }
            });
        }
    },

    makeForm: function(opts)
    {
        var store = new Ext.data.JsonStore({
            autoLoad: true,
            root: 'result',
            totalProperty: 'total',
            fields: ['id', 'title', 'fullname', 'slug', 'kind'],
            baseParams:{ area: opts.vals.area, exclude: opts.vals.id },
            url: action('CMS/get_superior_links/json')
        });

        var store_available = new Ext.data.JsonStore({
            //autoLoad: true,
            root: 'result',
            totalProperty: 'total',
            fields: ['id', 'name', 'fullname', 'slug', 'kind', 'url'],
            baseParams: {area: this.site, posts: 1},
            url: action('CMS/get_links_for_menu/json')
        });

        var store_site_url = new Ext.data.JsonStore({
            //autoLoad: true,
            root: 'result',
            totalProperty: 'total',
            fields: ['url'],
            baseParams: {site: this.site},
            url: action('CMS/get_site_url/json')
        });

        var kinds =  [
            {xtype: 'radio', boxLabel: 'Externo', name: 'kind', inputValue: 1},
            {xtype: 'radio', boxLabel: 'Superior', name: 'kind', inputValue: 0},
            {xtype: 'radio', boxLabel: 'Área', name: 'kind', inputValue: 2},
            {xtype: 'radio', boxLabel: 'Página', name: 'kind', inputValue: 3},
            {xtype: 'radio', boxLabel: 'Galeria', name: 'kind', inputValue: 4}
        ];

        var checkedRadio = null;
        Ext.each(kinds, function(item) {
            if(item.inputValue == opts.vals.kind)
            {
                item.checked = true;
                checkedRadio = item;
            }
        });

        var form = new ExtFormHelper({
            url: action('CMS/add_or_edit_link/json'),

            success: function(cmp, action){ },
            windowConfig: {
                title: opts.title
            },
            formConfig: {
                height: 500,
                width: 450,
                autoScroll: true,
                fileUpload: true,
                items: [
                    {
                        name: 'area',
                        value: opts.vals.area || '',
                        xtype: 'hidden'
                    },
                    {
                        name: 'id',
                        value: opts.vals.id || '',
                        xtype: 'hidden'
                    },
                    {
                        xtype: 'radiogroup',
                        fieldLabel: 'Tipo de Link',
                        itemCls: 'x-check-group-alt',
                        name: 'kinds',
                        items: kinds,
                        listeners: {
                            change: function(group, checked)
                            {
                                if(checked)
                                {
                                    var trueForm = form.items.items[0],
                                        value = checked.inputValue,
                                        available = getFieldByName(trueForm, 'available-items'),
                                        checkSame = getFieldByName(trueForm, 'same-title'),
                                        urlField = getFieldByName(trueForm, 'url');

                                    if(value == 0 || value == 1)
                                    {
                                        urlField.setReadOnly(false);
                                        available.hide();
                                        checkSame.hide();

                                        if(value == 0)
                                            urlField.setValue('#');
                                        // else if(value == 1)
                                        //     urlField.setValue('');
                                    }
                                    else
                                    {
                                        if(value == 4)
                                        {
                                            getFieldByName(trueForm, 'title').setValue('Galerias');
                                            store_site_url.on('load', function(){
                                                var site_url = store_site_url.getAt(0).get('url')
                                                urlField.setValue(site_url+'/galerias');
                                                urlField.setReadOnly(true);
                                                available.hide();
                                                checkSame.hide();
                                            });
                                            store_site_url.load();
                                        }
                                        else
                                        {
                                            new Ext.LoadMask(form.getEl(), {msg: 'Aguarde...', store: store_available});

                                            var loadOpts = {};
                                            if (value == 2)
                                                loadOpts = {params: {posts: 0}};

                                            store_available.on('load',
                                                function(store)
                                                {
                                                    var availableId = null;
                                                    store.each(function(record){
                                                        if(opts.vals.url && opts.vals.url.indexOf( record.get('slug') ) > -1)
                                                            available.setValue(record.get('id'));
                                                    });
                                                    available.show();
                                                    checkSame.show();
                                                }
                                            );
                                            store_available.load(loadOpts);
                                        }
                                    }
                                }
                            }
                        }
                    },
                    {
                        name: 'available-items',
                        fieldLabel: 'Itens disponíveis',
                        xtype: 'combo',
                        triggerAction: 'all',
                        hidden: true,
                        typeAhead: true,
                        mode: 'local',
                        width: 420,
                        store: store_available,
                        valueField: 'id',
                        displayField: 'fullname',
                        resizable: true,
                        listeners: {
                            select: function(cmp, record, index)
                            {
                                var urlField = getFieldByName(form.items.items[0], 'url');
                                urlField.setReadOnly(false);
                                urlField.setValue(record.get('url'));
                                urlField.setReadOnly(true);
                            }
                        }
                    },
                    {
                        xtype: 'checkbox',
                        fieldLabel: 'Mesmo título do item disponível?',
                        name: 'same-title',
                        hidden: true,
                        listeners: {
                            check: function(cmp, checked)
                            {
                                if(checked)
                                {
                                    var titleField = getFieldByName(form.items.items[0], 'title'),
                                        availableItemsField = getFieldByName(form.items.items[0], 'available-items'),
                                        store = availableItemsField.getStore();

                                    store.each(function(record){
                                        if(record.get('id') == availableItemsField.getValue())
                                        {
                                            titleField.setValue(record.get('name'));
                                            return false;
                                        }
                                    });
                                }
                            }
                        }
                    },
                    {
                        name: 'title',
                        fieldLabel: 'Título',
                        value: toolkit.util.replaceAll(opts.vals.title, '\\', '') || '',
                        xtype: 'textfield',
                        width: 420
                    },
                    {
                        name: 'position',
                        fieldLabel: 'Posição',
                        value: opts.vals.position || '',
                        xtype: 'textfield',
                        width: 50
                    },
                    {
                        name: 'url',
                        fieldLabel: 'URL',
                        value: opts.vals.url || '',
                        xtype: 'textfield',
                        width: 420
                    },
                    {
                        fieldLabel: 'Link Superior',
                        store: store,
                        xtype: 'combo',
                        triggerAction: 'all',
                        mode: 'local',
                        width: 420,
                        resizable: true,
                        hiddenName: 'parent',
                        hiddenValue: (opts.vals.parent=='root') ? '' : opts.vals.parent,
                        value: opts.vals.parentTitle || '',
                        valueField: 'id',
                        displayField: 'fullname'
                    },
                    {
                        name: 'image',
                        fieldLabel: 'Imagem',
                        xtype: 'fileuploadfield',
                        width: 420
                    },
                    {
                        fieldLabel: 'Imagem atual',
                        xtype: 'displayfield',
                        html: '<img src="'+opts.vals.image_url+'">'
                    }
                ]
            }
        });

        form.on('afterrender',
            function(c)
            {
                var radioGroup = getFieldByName(form.items.items[0], 'kinds');
                radioGroup.fireEvent('change', radioGroup, checkedRadio);
            }
        );

        return form;
    },

    getActionColumn: function() {
        if(!this._actionColumn)
            this._actionColumn = Ext._create('Ext.grid.ActionColumn', {
                width: 150,
                scope: this,
                items: [
                    {
                        tooltip: 'Visualizar ou Editar',
                        icon: icons+'edit.png',
                        handler: function(grid, row)
                        {
                            var record = grid.getStore().getAt(row);
                            this.makeForm({
                                title: 'Editar Link',
                                vals: {
                                    area: record.get('area'),
                                    parent: record.get('parent'),
                                    id: record.get('id'),
                                    parentTitle: record.get('parent_title'),
                                    title: record.get('title'),
                                    url: record.get('url_embed'),
                                    position: record.get('position'),
                                    kind: record.get('kind'),
                                    image_url: record.get('image_url')
                                }
                            }).show();
                        },
                        scope: this
                    },
                    {
                        tooltip:'Excluir',
                        icon: icons+'delete.png',
                        handler:function(grid, row, col)
                        {
                            var rec = grid.getStore().getAt(row);

                            xConfirm({
                                title:'Confirmação',
                                msg:'Confirma a exclusão do link: '+ rec.get('name') +' ?',
                                fn: function(btn)
                                {
                                    deleteItem({
                                        signal: btn,
                                        model: 'Link',
                                        pars: rec.get('id'),
                                        store: grid.getStore()
                                    });
                                }
                            });

                        },
                        scope:this
                    }
                ]
            });

        return this._actionColumn;
    },

    getConfigActionsItems: function(cfg){
        if(!this._configActionsItems){
            this._configActionsItems = {
                add:{
                    text: 'Novo',
                    iconCls: 'icon-16px icon-core icon-core-add',
                    scope: this,
                    handler: function()
                    { this.makeForm({title:'Adicionar Link', vals:{area: this.params.areas, position:9999}}).show(); },
                    scope: this
                },
                search:[
                    'Buscar por: ',
                    this.getKeywordField(cfg),
                    '-'
                ],
            }
        }
        return this._configActionsItems;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                callback: {
                    success: {
                        scope: this,
                        fn: function() {
                            this.getStore().reload();
                        }
                    }
                }
            }
        );
        Ext.apply(cfg,{
            columnAction: true,
        });

        web.intranet.link.Grid.superclass.constructor.call(this, cfg);
    }

});

core.RestfulGrid.register(
    'web.intranet.link.Restful',
    'web.intranet.link.Grid'
);
